using namespace std;
struct Pt{int x,y;};
bool coll(Pt a,Pt b,Pt c){return 1LL*(b.x-a.x)*(c.y-a.y)==1LL*(b.y-a.y)*(c.x-a.x);}
int potential(string const&s){Pt p[60];for(int i=0;i<30;i++){p[2*i]={i+1,(unsigned char)s[i]};p[2*i+1]={i+1,(unsigned char)s[30+i]};}int v=0;for(int i=0;i<60;i++)for(int j=i+1;j<60;j++)for(int k=j+1;k<60;k++)v+=coll(p[i],p[j],p[k]);return v;}
struct Move{int layer,i,j;};
Move parse(string const&m){int layer=m[0]=='b';auto c=m.find(':');auto q=m.find(',');return {layer,stoi(m.substr(c+1,q-c-1))-1,stoi(m.substr(q+1))-1};}
bool legal(string const&s,Move m){int o=30*m.layer,q=30*(1-m.layer);return (unsigned char)s[o+m.j]!=(unsigned char)s[q+m.i]&&(unsigned char)s[o+m.i]!=(unsigned char)s[q+m.j];}
string apply(string s,Move m){swap(s[30*m.layer+m.i],s[30*m.layer+m.j]);return s;}
string encode(vector<int> const&r,vector<int> const&b){string s;for(int x:r)s.push_back((char)x);for(int x:b)s.push_back((char)x);return s;}
vector<Move> all_moves(){vector<Move> out;for(int l=0;l<2;l++)for(int i=0;i<30;i++)for(int j=i+1;j<30;j++)out.push_back({l,i,j});return out;}
pair<size_t,bool> component(string const&start,int barrier,int target){auto moves=all_moves();unordered_set<string> seen;seen.reserve(100000);queue<string> q;seen.insert(start);q.push(start);bool lower=false;while(!q.empty()){string s=move(q.front());q.pop();for(auto m:moves){if(!legal(s,m))continue;string t=apply(s,m);if(seen.count(t))continue;int p=potential(t);if(p>barrier)continue;if(p<target)lower=true;seen.insert(t);q.push(move(t));}}return {seen.size(),lower};}
